(7550889, 1209571, 97225, '<td valign="top">Congrats on the HM. Great pose and great light. There is something fairy tale about this goose.</td>', 'Congrats on the HM. Great pose and great light. There is something fairy tale about this goose.', '2018-01-03 00:10:43.000000', NULL, 0),
(7550891, 1209523, 100831, '<td valign="top">Woo Hoo!   Congrats!  Fabulous image.</td>', 'Woo Hoo!   Congrats!  Fabulous image.', '2018-01-03 00:19:52.000000', NULL, 0),
(7550895, 1209523, 68504, '<td valign="top">how delightful!</td>', 'how delightful!', '2018-01-03 01:03:10.000000', NULL, 0),
(7550896, 1209472, 68504, '<td valign="top">ooh. love the eyes and the toe hairs. sweet.</td>', 'ooh. love the eyes and the toe hairs. sweet.', '2018-01-03 01:04:07.000000', NULL, 0),
(7550897, 1209472, 31637, '<td valign="top">The sun was setting so fast that I had to change camera settings every minute. I could''ve ramped the ISO up a bit but its tough exposing white birds without losing detail. I would''ve preferred to have the eyes open, even though closed eyes fits with the notion of meditation and yoga. Thanks for the comments everyone!</td>', 'The sun was setting so fast that I had to change camera settings every minute. I could''ve ramped the ISO up a bit but its tough exposing white birds without losing detail. I would''ve preferred to have the eyes open, even though closed eyes fits with the notion of meditation and yoga. Thanks for the comments everyone!', '2018-01-03 01:12:24.000000', NULL, 0),
(7550898, 1209585, 68504, '<td valign="top">I feel the heat, everything pulsing.</td>', 'I feel the heat, everything pulsing.', '2018-01-03 01:13:01.000000', NULL, 0),
(7550899, 1209568, 68504, '<td valign="top">pure magic!</td>', 'pure magic!', '2018-01-03 01:14:04.000000', NULL, 0),
