(7550901, 1209557, 68504, '<td valign="top">a smorgasbord of lines.</td>', 'a smorgasbord of lines.', '2018-01-03 01:20:36.000000', NULL, 0),
(7550902, 1209301, 68504, '<td valign="top">wish I had voted. this is a gorgeous breakthrough of spirit.</td>', 'wish I had voted. this is a gorgeous breakthrough of spirit.', '2018-01-03 01:22:24.000000', NULL, 0),
